#include <stdio.h>
/* ex09：信道利用率 —— 停等协议为什么在长肥管道上效率极低
 * 停等协议：发一帧 -> 等 ACK -> 再发下一帧
 * 信道利用率 U = Td / (Td + RTT + Ta)
 *   Td  = 帧的发送时延
 *   RTT = 往返传播时延
 *   Ta  = ACK 的发送时延（通常很小）
 * 「带宽时延积大 + 帧短」= 长肥管道（Long Fat Network），U 会低到无法接受。*/
int main(void) {
    struct { const char *name; double Mbps; double rtt_ms; int frame_bit; } cases[] = {
        {"局域网 1Gbps/0.1ms", 1000.0,   0.1, 12000},
        {"城域 100Mbps/2ms",    100.0,   2.0, 12000},
        {"跨省 100Mbps/40ms",   100.0,  40.0, 12000},
        {"卫星 50Mbps/540ms",    50.0, 540.0, 12000}
    };

    printf("停等协议：每发一帧就要等一个 RTT，利用率 U = Td/(Td+RTT+Ta)\n");
    printf("--------------------------------------------------------------------------\n");
    printf("%-22s %-14s %-14s %-12s %s\n", "链路", "帧发送时延Td", "RTT", "利用率U", "评价");
    for (int i = 0; i < 4; i++) {
        double rate = cases[i].Mbps * 1e6;
        double td_ms = cases[i].frame_bit / rate * 1000.0;
        double u = td_ms / (td_ms + cases[i].rtt_ms) * 100.0;
        printf("%-22s %-14.3f %-14.1f %-12.1f %s\n", cases[i].name, td_ms, cases[i].rtt_ms, u,
               u > 90 ? "可以接受" : u > 30 ? "偏低，考虑流水线" : "极低，必须用滑动窗口");
    }
    printf("--------------------------------------------------------------------------\n");
    printf("关键结论：\n");
    printf("  1) 帧越短、RTT 越大，停等协议越亏 —— 因为「等待」占了绝大部分时间；\n");
    printf("  2) 解决办法不是加带宽（反而让 Td 更小、U 更低！），\n");
    printf("     而是「流水线」：连续发多个帧，用滑动窗口把 RTT 填满（GBN/SR）；\n");
    printf("  3) 这也解释了为什么卫星链路必须用大窗口 TCP（窗口 ≥ 带宽时延积）。\n");
    return 0;
}
